public interface INotifier { Task SendAsync(string message); }
public class EmailNotifier : INotifier
{
    private readonly SmtpClient _client;
    public EmailNotifier(SmtpClient client) => _client = client;
    public async Task SendAsync(string message) => await _client.SendMailAsync(message);
}

public class SmsNotifier : INotifier
{
    private readonly SmsClient _client;
    public SmsNotifier(SmsClient client) => _client = client;
    public async Task SendAsync(string message) => await _client.SendAsync(message);
}

// Register multiple implementations
builder.Services.AddTransient<EmailNotifier>();
builder.Services.AddTransient<SmsNotifier>();

// Factory that chooses based on a setting
builder.Services.AddTransient<INotifier>(sp =>
{
    var config = sp.GetRequiredService<IConfiguration>();
    var channel = config["NotificationChannel"];
    return channel == "sms"
        ? sp.GetRequiredService<SmsNotifier>()
        : sp.GetRequiredService<EmailNotifier>();
});

public class NotificationService(INotifier notifier)
{
    public async Task NotifyAsync(string message) => await notifier.SendAsync(message);
}

builder.Services.AddKeyedScoped<INotifier, EmailNotifier>("email");
builder.Services.AddKeyedScoped<INotifier, SmsNotifier>("sms");
builder.Services.AddKeyedScoped<INotifier, PushNotifier>("push");

// Consume with IKeyedServiceProvider
public class NotificationController(IKeyedServiceProvider provider) : Controller
{
    public async Task<IActionResult> Send(string channel, string message)
    {
        var notifier = provider.GetRequiredKeyedService<INotifier>(channel);
        await notifier.SendAsync(message);
        return Ok();
    }
}

