public interface IProductRepository
{
    Task<Product> GetByIdAsync(int id);
    Task<List<Product>> GetAllAsync();
}

public class EfProductRepository : IProductRepository
{
    private readonly AppDbContext _db;
    public EfProductRepository(AppDbContext db) => _db = db;
    public async Task<Product> GetByIdAsync(int id) => await _db.Products.FindAsync(id);
    public async Task<List<Product>> GetAllAsync() => await _db.Products.ToListAsync();
}

public class CachingProductRepository : IProductRepository
{
    private readonly IProductRepository _inner;
    private readonly ICacheService _cache;

    public CachingProductRepository(IProductRepository inner, ICacheService cache)
    {
        _inner = inner;
        _cache = cache;
    }

    public async Task<Product> GetByIdAsync(int id)
    {
        return await _cache.GetOrCreateAsync(
            "product-" + id,
            async () => await _inner.GetByIdAsync(id));
    }

    public async Task<List<Product>> GetAllAsync() => await _inner.GetAllAsync();
}

// Registration
builder.Services.AddScoped<IProductRepository, EfProductRepository>();
builder.Services.Decorate<IProductRepository, CachingProductRepository>();
